496	  private static Throwable walkCausalChain(
497	      Throwable throwable, @Nullable List<Throwable> causes) {
498	    if (causes != null) {
499	      causes.add(throwable);
500	    }
501	
502	    // Keep a second pointer that slowly walks the causal chain. If the fast pointer ever catches
503	    // the slower pointer, then there's a loop.
504	    Throwable slowPointer = throwable;
505	    boolean advanceSlowPointer = false;
506	
507	    Throwable cause;
508	    while ((cause = throwable.getCause()) != null) {
509	      throwable = cause;
510	      if (causes != null) {
511	        causes.add(throwable);
512	      }
513	
514	      if (throwable == slowPointer) {
515	        throw new IllegalArgumentException("Loop in causal chain detected.", throwable);
516	      }
517	      if (advanceSlowPointer) {
518	        slowPointer = slowPointer.getCause();
519	      }
520	      advanceSlowPointer = !advanceSlowPointer; // only advance every other iteration
521	    }
522	    return throwable;
523	  }
