525	  @J2ktIncompatible
526	  @GwtIncompatible // java.lang.reflect
527	  private static @Nullable Method getJlaMethod(String name, Class<?>... parameterTypes) {
528	    try {
529	      return Class.forName(JAVA_LANG_ACCESS_CLASSNAME, false, null).getMethod(name, parameterTypes);
530	    } catch (Throwable t) {
531	      throwIfThreadDeath(t);
532	      /*
533	       * Either the JavaLangAccess class itself is not found, or the method is not supported on the
534	       * JVM.
535	       */
536	      return null;
537	    }
538	  }
