497	  /**
498	   * Ensures that {@code reference} is non-null, throwing a {@code VerifyException} with a default
499	   * message otherwise.
500	   *
501	   * @return {@code reference}, guaranteed to be non-null, for convenience
502	   * @throws VerifyException if {@code reference} is {@code null}
503	   * @see Preconditions#checkNotNull Preconditions.checkNotNull()
504	   */
505	  @CanIgnoreReturnValue
506	  public static <T> T verifyNotNull(@Nullable T reference) {
507	    return verifyNotNull(reference, "expected a non-null reference");
508	  }
