510	  /**
511	   * Ensures that {@code reference} is non-null, throwing a {@code VerifyException} with a custom
512	   * message otherwise.
513	   *
514	   * @param errorMessageTemplate a template for the exception message should the check fail. The
515	   *     message is formed by replacing each {@code %s} placeholder in the template with an
516	   *     argument. These are matched by position - the first {@code %s} gets {@code
517	   *     errorMessageArgs[0]}, etc. Unmatched arguments will be appended to the formatted message in
518	   *     square braces. Unmatched placeholders will be left as-is.
519	   * @param errorMessageArgs the arguments to be substituted into the message template. Arguments
520	   *     are converted to strings using {@link String#valueOf(Object)}.
521	   * @return {@code reference}, guaranteed to be non-null, for convenience
522	   * @throws VerifyException if {@code reference} is {@code null}
523	   * @see Preconditions#checkNotNull Preconditions.checkNotNull()
524	   */
525	  @CanIgnoreReturnValue
526	  public static <T> T verifyNotNull(
527	      @Nullable T reference,
528	      String errorMessageTemplate,
529	      @Nullable Object @Nullable ... errorMessageArgs) {
530	    if (reference == null) {
531	      throw verifyException(errorMessageTemplate, errorMessageArgs);
532	    }
533	    return reference;
534	  }
